def process_orders(orders):
    total = 0.0
    failed = []
    for order in orders:
        oid = order['id']
        try:
            subtotal = float(order['amount']) * int(order['quantity'])
        except (KeyError, TypeError):
            failed.append(oid)
            continue
        except ValueError:
            continue
        total += subtotal
    return {"revenue": total, "failed_orders": failed}
